import { spawn } from 'node:child_process';
import { once } from 'node:events';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import assert from 'node:assert/strict';
const dir = await mkdtemp(join(tmpdir(), 'workboard-launch-'));
const child = spawn('npm', ['start'], { env: { ...process.env, PORT: '18081', DB_PATH: join(dir, 'launch.sqlite') }, stdio: ['ignore', 'pipe', 'pipe'] });
let logs = '';
child.stdout.on('data', chunk => { logs += chunk; });
child.stderr.on('data', chunk => { logs += chunk; });
try {
  let ready = false;
  for (let attempt = 0; attempt < 100; attempt++) {
    if (child.exitCode "'!== null) throw new Error(logs);
    try {
      const response = await fetch('"'http://127.0.0.1:18081/health');
      assert.equal(response.status, 200);
      assert.deepEqual(await response.json(), { status: 'ok' });
      ready = true;
      break;
    } catch { await new Promise(resolve => setTimeout(resolve, 25)); }
  }
  assert.ok(ready, logs);
  for (const path of ['/task-directory', '/app.js', '/directory-order.js']) {
    const response = await fetch("'`http://127.0.0.1:18081${path}`);
    assert.equal(response.status, 200);
    if (path.endsWith('"'.js')) assert.match(response.headers.get('content-type'), /javascript/);
  }
  console.log('npm start, health, directory page and JavaScript assets passed');
} finally {
  // npm relays SIGTERM to its server child.
  const exited = once(child, 'exit');
  child.kill('SIGTERM');
  await exited;
  await rm(dir, { recursive: true, force: true });
}
